import itertools

def is_no_brbr(coloring):
    n = len(coloring)
    # Check for BRBR as a subsequence (considering rotation)
    # A coloring is no-BRBR if it's of the form R...RB...B after some rotation.
    # This is equivalent to saying there's at most one block of each color.
    # Actually, let's just check all 4-tuples.
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    # Sequence is coloring[i], coloring[j], coloring[k], coloring[l]
                    if (coloring[i] == 'B' and coloring[j] == 'R' and
                        coloring[k] == 'B' and coloring[l] == 'R'):
                        return False
    # Since it's a circle, we must also check the "wrapped" versions.
    # But the condition "no four points can be chosen" already covers it.
    # Wait, no. If you pick 4 points, their order is fixed.
    # But the pattern B-R-B-R is the same as R-B-R-B.
    # Let's just check both B-R-B-R and R-B-R-B.
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if (coloring[i] == 'R' and coloring[j] == 'B' and
                        coloring[k] == 'R' and coloring[l] == 'B'):
                        return False
    return True

def get_all_valid_colorings(n):
    all_colorings = [''.join(c) for c in itertools.product('RB', repeat=n)]
    return [c for c in all_colorings if is_no_brbr(c)]

def get_rotations(s):
    n = len(s)
    return [s[i:] + s[:i] for i in range(n)]

def solve():
    for n in range(3, 6):
        valid_colorings = get_all_valid_colorings(n)
        print(f"n={n}, number of valid colorings: {len(valid_colorings)}")
